  "Pen detected: pressure {min} to {max}, twist.": "Pero otkriveno: pritisak od {min} do {max}, okretanje.", "Pen detected: pressure {min} to {max}.": "Pero otkriveno: pritisak od {min} do {max}.", "Count-in · {n}": "Odbrojavanje · {n}", "Action · {mode}": "Radnja · {mode}",
